import{_ as t,o as a,c as o,a7 as r}from"./chunks/framework.C4ZIv4ii.js";const n="/falconcms/screenshots/slider-layer.webp",u=JSON.parse('{"title":"Layers","description":"","frontmatter":{},"headers":[],"relativePath":"slider/layers.md","filePath":"slider/layers.md","lastUpdated":1788112837000}'),s={name:"slider/layers.md"};function i(l,e,d,h,c,g){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="layers" tabindex="-1">Layers <a class="header-anchor" href="#layers" aria-label="Permalink to &quot;Layers&quot;">​</a></h1><p><strong>Layers</strong> are the building blocks placed on top of a slide&#39;s background — headlines, buttons, images, timers and more. Each layer is freely positioned, sized, styled, made responsive per device, and <a href="/falconcms/slider/animations.html">animated</a> on its own schedule.</p><p><img src="'+n+'" alt="A layer selected in the slider editor"></p><p><em>Selecting a layer — on the canvas, in the list, or on its timeline bar — opens its properties: text and SEO tag, reveal, link, and the effect sliders.</em></p><hr><h2 id="adding-a-layer" tabindex="-1">Adding a layer <a class="header-anchor" href="#adding-a-layer" aria-label="Permalink to &quot;Adding a layer&quot;">​</a></h2><p>Click <strong>+ Add Layer</strong> in the toolbar and choose a type:</p><table tabindex="0"><thead><tr><th>Layer</th><th>Use it for</th></tr></thead><tbody><tr><td><strong>Text</strong></td><td>Headlines, paragraphs, captions — with real <code>h1</code>–<code>h6</code> / <code>p</code> tags for SEO</td></tr><tr><td><strong>Image</strong></td><td>Logos, product shots, decorations</td></tr><tr><td><strong>Button</strong></td><td>Call-to-action links with hover states</td></tr><tr><td><strong>Shape</strong></td><td>Rectangles, circles and polygons — solid fills or full-width overlays</td></tr><tr><td><strong>Icon</strong></td><td>Any of the bundled Material Symbols icons</td></tr><tr><td><strong>Video</strong></td><td>Inline video (self-hosted, YouTube or Vimeo) with optional controls</td></tr><tr><td><strong>Audio</strong></td><td>An inline audio player</td></tr><tr><td><strong>Countdown</strong></td><td>A live-ticking days/hours/mins/secs timer to a target date</td></tr><tr><td><strong>HTML / Embed</strong></td><td>Raw HTML — forms, maps, third-party embeds</td></tr></tbody></table><p>The new layer appears on the canvas and in the <strong>Layers</strong> tab, selected and ready to edit.</p><hr><h2 id="positioning-sizing" tabindex="-1">Positioning &amp; sizing <a class="header-anchor" href="#positioning-sizing" aria-label="Permalink to &quot;Positioning &amp; sizing&quot;">​</a></h2><ul><li><strong>Drag</strong> a layer on the canvas to move it; drag its handles to resize.</li><li>Use the <strong>arrow keys</strong> to nudge the selected layer (hold <strong>Shift</strong> for 10px steps).</li><li><strong>Delete / Backspace</strong> removes the selected layer.</li><li>Snapping guides help you align to other layers and the slide centre.</li></ul><p>Every position and size is stored per device — see <a href="#responsive-layers">Responsive layers</a>.</p><hr><h2 id="layer-types-in-depth" tabindex="-1">Layer types in depth <a class="header-anchor" href="#layer-types-in-depth" aria-label="Permalink to &quot;Layer types in depth&quot;">​</a></h2><h3 id="text" tabindex="-1">Text <a class="header-anchor" href="#text" aria-label="Permalink to &quot;Text&quot;">​</a></h3><p>Type your copy and style it: font family (Google Fonts), size, weight, colour, alignment, line-height, letter-spacing and shadow. For SEO, set the <strong>tag</strong> to <code>h1</code>–<code>h6</code> or <code>p</code> and the layer renders as that real element. Text layers also support animated <a href="/falconcms/slider/animations.html#text-reveal">reveals</a>.</p><h3 id="button" tabindex="-1">Button <a class="header-anchor" href="#button" aria-label="Permalink to &quot;Button&quot;">​</a></h3><p>A real <code>&lt;a&gt;</code> link with its own <strong>URL</strong> and optional <strong>new-tab</strong>. Style the background, text colour, size, weight, radius and border, plus <strong>hover</strong> background/text colours. Pick from ready-made <strong>button styles</strong> when you add one.</p><h3 id="image" tabindex="-1">Image <a class="header-anchor" href="#image" aria-label="Permalink to &quot;Image&quot;">​</a></h3><p>Choose an image and a <strong>fit</strong> (<code>cover</code>, <code>contain</code>, <code>fill</code>, <code>none</code>) and corner <strong>radius</strong>. Image layers load lazily with their slide.</p><h3 id="shape" tabindex="-1">Shape <a class="header-anchor" href="#shape" aria-label="Permalink to &quot;Shape&quot;">​</a></h3><p>Squares (with radius), circles, and polygon shapes via clip-path. Mark a shape <strong>full-width</strong> to turn it into a background-level overlay band that spans the whole frame behind your text.</p><h3 id="icon" tabindex="-1">Icon <a class="header-anchor" href="#icon" aria-label="Permalink to &quot;Icon&quot;">​</a></h3><p>Insert any bundled <strong>Material Symbols</strong> icon. Only the glyphs actually used are downloaded (subset loading). The glyph scales to fill the layer box.</p><h3 id="video-audio" tabindex="-1">Video &amp; Audio <a class="header-anchor" href="#video-audio" aria-label="Permalink to &quot;Video &amp; Audio&quot;">​</a></h3><p>Inline <strong>video</strong> (self-hosted / YouTube / Vimeo) with autoplay, mute, loop and controls toggles. Inline <strong>audio</strong> with a standard player. These are <em>interactive</em> layers — they keep their own controls even when the slide has a <a href="/falconcms/slider/slides.html#whole-slide-link">whole-slide link</a>.</p><h3 id="countdown" tabindex="-1">Countdown <a class="header-anchor" href="#countdown" aria-label="Permalink to &quot;Countdown&quot;">​</a></h3><p>A live countdown to a target date/time, showing <strong>Days · Hours · Mins · Secs</strong>. Style the numbers and labels, and set the text/colour shown when the countdown <strong>expires</strong>.</p><h3 id="html-embed" tabindex="-1">HTML / Embed <a class="header-anchor" href="#html-embed" aria-label="Permalink to &quot;HTML / Embed&quot;">​</a></h3><p>Drop in raw HTML for forms, maps or any third-party embed. Rendered as-is inside the layer box.</p><hr><h2 id="layer-links" tabindex="-1">Layer links <a class="header-anchor" href="#layer-links" aria-label="Permalink to &quot;Layer links&quot;">​</a></h2><p>Any non-button layer (text, image, shape, icon) can be given its own <strong>link</strong> with an optional new-tab — a full-cover anchor is added with real link semantics. This takes precedence over a <a href="/falconcms/slider/slides.html#whole-slide-link">whole-slide link</a>.</p><hr><h2 id="responsive-layers" tabindex="-1">Responsive layers <a class="header-anchor" href="#responsive-layers" aria-label="Permalink to &quot;Responsive layers&quot;">​</a></h2><p>Switch the device toggle (<strong>Desktop / Tablet / Mobile</strong>) in the toolbar and every change you make is stored <strong>for that breakpoint</strong>:</p><ul><li><strong>Position &amp; size</strong> — reposition and resize per device</li><li><strong>Font size</strong> — text and button sizes per device</li><li><strong>Visibility</strong> — hide any layer on specific devices</li></ul><p>The breakpoints (tablet / mobile widths) are set in the slider <strong>Settings</strong> tab. On the frontend the runtime picks the right layout for the visitor&#39;s screen and repositions layers live on resize/rotate.</p><hr><h2 id="layer-groups" tabindex="-1">Layer groups <a class="header-anchor" href="#layer-groups" aria-label="Permalink to &quot;Layer groups&quot;">​</a></h2><p>Select multiple layers and <strong>group</strong> them. A group lets you:</p><ul><li><strong>Hide the whole group</strong> per device in one toggle</li><li>Apply a <strong>group animation</strong> with a <strong>stagger</strong> — members animate in one after another automatically</li></ul><p>Layers without their own animation inherit the group&#39;s preset and staggered delay.</p><hr><h2 id="global-layers" tabindex="-1">Global layers <a class="header-anchor" href="#global-layers" aria-label="Permalink to &quot;Global layers&quot;">​</a></h2><p>A <strong>global layer</strong> is drawn on <em>every</em> slide — ideal for a logo, watermark or a fixed call-to-action that should persist as slides change. Edit global layers from the editor&#39;s global-layers mode; they render on top of each slide&#39;s own layers.</p><hr><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/falconcms/slider/animations.html">Animations</a> — bring every layer in with entrance, reveal and idle-loop animation</li><li><a href="/falconcms/slider/navigation.html">Navigation &amp; Managing</a> — arrows, autoplay, revisions and preview</li></ul>',50)])])}const y=t(s,[["render",i]]);export{u as __pageData,y as default};
